window.__USERTYPO_GET_PAGE_FRAGMENT__ = function (pagePath) {
    var pages = window.__USERTYPO_PAGE_FRAGMENTS__;
    if (!pages || !pagePath) return null;
    if (pages[pagePath]) return pages[pagePath];
    var normalized = String(pagePath).replace(/^\/+/, '');
    if (pages[normalized]) return pages[normalized];
    if (pages['pages/' + normalized.replace(/^pages\//, '')]) {
        return pages['pages/' + normalized.replace(/^pages\//, '')];
    }
    return null;
};
